cess\\\")\\n   157\\t\\n   158\\t\\n   159\\tdef check_review(number: int, head_sha: str, reviews: list[dict], statuses: dict,\\n   160\\t                 *, adjudicated: bool) -> None:\\n   161\\t    \\\"\\\"\\\"Gate 4 — one verdict review on this commit id, clean or adjudicated.\\\"\\\"\\\"\\n   162\\t    marker = f\\\"<!-- mipstarre-review pr={number} head={head_sha} -->\\\"\\n   163\\t    matching = [r for r in reviews\\n   164\\t                if r.get(\\\"commit_id\\\") == head_sha and marker in (r.get(\\\"body\\\") or \\\"\\\")]\\n   165\\t    if not matching:\\n   166\\t        raise GateFailure(f\\\"gate 4 (review): no review carrying {marker} on commit \\\"\\n   167\\t                          f\\\"{head_sha[:12]}, required exactly one. A verdict on an earlier SHA \\\"\\n   168\\t                          \\\"does not carry over (DESIGN.md:66-69): re-run review.sh.\\\")\\n   169\\t    # One verdict review per head is the contract; if a retry ever leaves two, the newest\\n   170\\t    # is operative (the API returns reviews in creation order).\\n   171\\t    body = matching[-1].get(\\\"body\\\") or \\\"\\\"\\n   172\\t    found = VERDICT_RE.search(body)\\n   173\\t    verdict = found.group(1) if found else \\\"\\\"\\n   174\\t    unchecked = len(UNCHECKED_FINDING_RE.findall(body))\\n   175\\t    summary_state = (statuses.get(REVIEW_CONTEXT) or {}).get(\\\"state\\\")\\n   176\\t    # Green needs BOTH a clean verdict and a clean ledger: an APPROVED trailer\\n   177\\t    # over unresolved findings is inconsistent reviewer output (round 2, F4).\\n   178\\t    clean = verdict in (\\\"APPROVED\\\", \\\"COMMENTED\\\") and unchecked == 0\\n   179\\t    if clean and summary_state == \\\"success\\\":\\n   180\\t        passed(f\\\"gate 4 verdict {verdict} on {head_sha[:12]}, {REVIEW_CONTEXT} success\\\")\\n   181\\t        return\\n   182\\t    observed = (f\\\"VERDICT {verdict or 'absent'} with {unchecked} unchecked finding(s), \\\"\\n   183\\t                f\\\"{REVIEW_CONTEXT} {summary_state or 'MISSING'}\\\")\\n   184\\t    if not adjudicated:\\n   185\\t        raise GateFailure(f\\\"gate 4 (review): required VERDICT APPROVED, or COMMENTED with zero \\\"\\n   186\\t                          f\\\"unchecked findings, and {REVIEW_CONTEXT} success; observed \\\"\\n …252152 tokens truncated…uli-appendix} is monotonically increasing in $a$, so without loss of generality we may assume that $a\\\\\\\\n   251\\\\\\\\t  \\\\\\\\\\\\\\\\geq 6$.  Then it follows that we may assume that $6md \\\\\\\\\\\\\\\\leq q$\\\\\\\\n   252\\\\\\\\t  without loss of generality, since otherwise, $\\\\\\\\\\\\\\\\delta \\\\\\\\\\\\\\\\geq a md /q\\\\\\\\n   253\\\\\\\\t  \\\\\\\\\\\\\\\\geq 1$ and the conclusion of the theorem holds trivially.\\\\\\\\n   254\\\\\\\\t  The same lower bound holds for the probability that $\\\\\\\\\\\\\\\\omega$ is anticommuting.\\\\\\\\n   255\\\\\\\\t  Therefore, the consistency conditions in\\\\\\\\n\\\\\\\",\\\\\\\"exit_code\\\\\\\":0,\\\\\\\"status\\\\\\\":\\\\\\\"completed\\\\\\\"}}\\\\n     1\\\\t## Findings\\\\n     2\\\\t\\\\n     3\\\\t- [ ] F1 (blocker) `blueprint/src/chapter/ch15_qpbt_combining.tex:431` — `lem:qld-4-13` adds a non-source divisibility hypothesis and changes the cited error term.\\\\n     4\\\\t- [ ] F2 (blocker) `blueprint/src/chapter/ch15_qpbt_combining.tex:541` — `lem:qld-sublines` adds the load-bearing hypothesis `2m+2 ∣ q`.\\\\n     5\\\\t- [ ] F3 (blocker) `blueprint/src/chapter/ch15_qpbt_combining.tex:1031` — `lem:qld-4-7` is presented under its paper label despite a new restriction excluding all admissible `m ≥ 2`.\\\\n     6\\\\t- [ ] F4 (blocker) `blueprint/src/chapter/ch16_qpbt_extraction.tex:279` — the proof of unrestricted `thm:pauli` depends on the restricted `lem:qld-4-7`.\\\\n     7\\\\t- [ ] F5 (blocker) `blueprint/src/chapter/ch12_qpbt_games.tex:123` — `lem:symmetric-strat` weakens the source conclusion by introducing `ε' > ε`.\\\\n     8\\\\t- [ ] F6 (blocker) `blueprin