47:+/-- Two finite distributions coincide as soon as their supports and their
48:+weight functions coincide.  Formalization-only extensionality principle for
49:+`Distribution`. -/
50:+theorem Distribution.ext_of_support_of_weight {α : Type*} {μ ν : Distribution α}
51:+    (hsupport : μ.support = ν.support) (hweight : μ.weight = ν.weight) :
52:+    μ = ν := by
53:+  cases μ with
54:+  | mk s w hn ho =>
55:+    cases ν with
56:+    | mk s' w' hn' ho' =>
57:+      have hs : s = s' := hsupport
58:+      have hw : w = w' := hweight
59:+      subst hs
60:+      subst hw
61:+      rfl
63:+/-- Successive push-forwards of a finite distribution compose.
64:+Formalization-only auxiliary for `Distribution.map`. -/
65:+theorem Distribution.map_map {α β γ : Type*}
66:+    [DecidableEq β] [DecidableEq γ]
67:+    (μ : Distribution α) (e : α → β) (f : β → γ) :
68:+    (μ.map e).map f = μ.map fun a => f (e a) := by
69:+  refine Distribution.ext_of_support_of_weight ?_ ?_
70:+  · change (μ.support.image e).image f = μ.support.image fun a => f (e a)
71:+    rw [Finset.image_image]
72:+    rfl
73:+  · funext c
74:+    have hmaps : ∀ a ∈ μ.support.filter fun a => f (e a) = c,
75:+        e a ∈ (μ.support.image e).filter fun b => f b = c := by
76:+      intro a ha
77:+      obtain ⟨ha1, ha2⟩ := Finset.mem_filter.mp ha
78:+      exact Finset.mem_filter.mpr ⟨Finset.mem_image_of_mem _ ha1, ha2⟩
79:+    have hkey := Finset.sum_fiberwise_of_maps_to hmaps μ.weight
80:+    change (∑ b ∈ (μ.support.image e).filter fun b => f b = c,
81:+        ∑ a ∈ μ.support.filter fun a => e a = b, μ.weight a) =
82:+      ∑ a ∈ μ.support.filter fun a => f (e a) = c, μ.weight a
83:+    rw [← hkey]
84:+    refine Finset.sum_congr rfl fun b hb => ?_
85:+    obtain ⟨-, hb2⟩ := Finset.mem_filter.mp hb
86:+    congr 1
87:+    ext a
88:+    simp only [Finset.mem_filter]
89:+    constructor
90:+    · rintro ⟨ha1, rfl⟩
91:+      exact ⟨⟨ha1, hb2⟩, rfl⟩
92:+    · rintro ⟨⟨ha1, -⟩, hae⟩
93:+      exact ⟨ha1, hae⟩
